function findAmcPlan(id,type){return (db.amcPlans||[]).find(p=>p.id===id)||(db.amcPlans||[]).find(p=>p.name.toLowerCase()===String(type||'').toLowerCase())}
function effectiveCustomerAmc(c){if(!c)return null;let plan=findAmcPlan(c.amcPlanId,c.amcType);return {...c,amcType:plan?.name||c.amcType||'',amcPlanId:plan?.id||c.amcPlanId||'',amcNotes:c.amcNotes||plan?.coverage||''}}
