function suggestedAmcExpiry(start,months){if(!validAmcDate(start)||!Number.isInteger(Number(months))||months<1||months>120)return '';let date=new Date(start+'T00:00:00Z'),day=date.getUTCDate();date.setUTCDate(1);date.setUTCMonth(date.getUTCMonth()+Number(months));let last=new Date(Date.UTC(date.getUTCFullYear(),date.getUTCMonth()+1,0)).getUTCDate();date.setUTCDate(Math.min(day,last));date.setUTCDate(date.getUTCDate()-1);return date.toISOString().slice(0,10)}
function createSharedAmcPlan(input){let name=String(input.name||'').trim(),months=Number(input.months),coverage=String(input.coverage||'').trim();if(!name||name.length>80)throw Error('Enter a plan name, up to 80 characters.');if(!Number.isInteger(months)||months<1||months>120)throw Error('Validity must be 1–120 whole months.');if((db.amcPlans||[]).some(p=>p.name.toLowerCase()===name.toLowerCase()))throw Error('An AMC plan with this name already exists.');let before=structuredClone(db),plan={id:'AMC-PLAN-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),name,months,coverage:coverage.slice(0,1000)};db.amcPlans.push(plan);db.lists['AMC Types']=db.lists['AMC Types']||[];if(!db.lists['AMC Types'].some(v=>v.toLowerCase()===name.toLowerCase()))db.lists['AMC Types'].push(name);audit('AMC Plan',name+' created');if(save('AMC plan created and synced')===false){db=before;return null}return plan}
