function setupInlineAmcPlan(key,id){let form=$('#recordForm');if(!form)return;let type=form.querySelector('[name="amcType"]'),planId=form.querySelector('[name="amcPlanId"]');if(!type||!planId)return;planId.closest('.field').classList.add('amcInternalField');let scope=form.querySelector('[name="amcScope"]'),current=id?find(key,id):{};if(current?.amcType&&!Array.from(type.options).some(o=>o.value===current.amcType)){let option=document.createElement('option');option.value=option.textContent=current.amcType;type.appendChild(option);type.value=current.amcType}let matched=findAmcPlan(planId.value,type.value);if(matched)planId.value=matched.id;let panel=document.createElement('div');panel.className='inlineAmcPlan';panel.innerHTML='<button type="button" class="btn secondary small" data-amc-open-create>+ Add AMC Plan</button><div data-amc-create-fields hidden><label class="field"><span>Plan Name</span><input data-amc-new-name maxlength="80"></label><label class="field"><span>Default Validity (Months)</span><input data-amc-new-months type="number" min="1" max="120" value="12"></label><label class="field"><span>Coverage / Plan Notes</span><textarea data-amc-new-coverage maxlength="1000"></textarea></label><button type="button" class="btn small" data-amc-create-save>Create & Select Plan</button><button type="button" class="btn secondary small" data-amc-create-cancel>Cancel</button><p data-amc-create-status role="status"></p></div><p data-amc-effective-status></p>';type.closest('.field').after(panel);let fields=panel.querySelector('[data-amc-create-fields]');panel.querySelector('[data-amc-open-create]').onclick=()=>{fields.hidden=!fields.hidden;if(!fields.hidden)fields.querySelector('input').focus()};panel.querySelector('[data-amc-create-cancel]').onclick=()=>fields.hidden=true;
 function sync(suggest=false){let plan=findAmcPlan('',type.value);planId.value=plan?.id||'';if(suggest&&plan){let start=form.querySelector('[name="amcStart"]'),expiry=form.querySelector('[name="amcExpiry"]');if(!start.value)start.value=today();if(!expiry.value)expiry.value=suggestedAmcExpiry(start.value,plan.months);}if(scope){let inherited=scope.value!=='vehicle';for(let name of ['amcType','amcStart','amcExpiry','amcRef','amcNotes']){let input=form.querySelector('[name="'+name+'"]');input.closest('.field').classList.toggle('amcInheritedField',inherited)}panel.querySelector('[data-amc-open-create]').textContent=inherited?'+ Add Vehicle AMC Plan':'+ Add AMC Plan';let c=effectiveCustomerAmc(find('customers',form.querySelector('[name="customer"]')?.value));panel.querySelector('[data-amc-effective-status]').textContent=scope.value==='customer'?'Using customer AMC: '+(c?.amcType||'No AMC')+(c?.amcExpiry?' · Valid until '+c.amcExpiry:''):scope.value==='none'?'No AMC for this vehicle.':'This vehicle has its own AMC plan and validity.'}}
 type.addEventListener('change',()=>{if(scope)scope.value='vehicle';sync(true)});if(scope)scope.addEventListener('change',()=>sync(false));form.querySelector('[name="customer"]')?.addEventListener('change',()=>sync(false));panel.querySelector('[data-amc-create-save]').onclick=()=>{try{let plan=createSharedAmcPlan({name:panel.querySelector('[data-amc-new-name]').value,months:panel.querySelector('[data-amc-new-months]').value,coverage:panel.querySelector('[data-amc-new-coverage]').value});if(!plan)return;let option=document.createElement('option');option.value=option.textContent=plan.name;type.appendChild(option);type.value=plan.name;if(scope)scope.value='vehicle';fields.hidden=true;sync(true)}catch(err){panel.querySelector('[data-amc-create-status]').textContent=err.message}};sync();let submit=form.onsubmit;form.onsubmit=e=>{let data=Object.fromEntries(new FormData(form));try{if(key==='bikes'&&data.amcScope==='vehicle')validateCustomerAmc(data)}catch(err){e.preventDefault();return toast(err.message)}return submit(e)}}
