function amcContractEntries(){let customers=db.customers.map(effectiveCustomerAmc).filter(c=>c.amcType).map(c=>({...c,contractKey:'customers',contractId:c.id,vehicleNumbers:db.bikes.filter(b=>b.customer===c.id&&b.amcScope!=='vehicle'&&b.amcScope!=='none').map(b=>b.number).join(', '),amcSource:'Customer AMC'}));let vehicles=db.bikes.filter(b=>b.amcScope==='vehicle'&&b.amcType).map(b=>{let c=find('customers',b.customer),amc=effectiveVehicleAmc(b);return {...amc,name:c?.name||'Customer not found',mobile:c?.mobile||'',contractKey:'bikes',contractId:b.id,customer:b.customer,vehicleNumbers:b.number}});return [...customers,...vehicles]}
function contractReminderLog(entry){return (db.amcReminderLogs||[]).filter(l=>(entry.contractKey==='bikes'?l.vehicle===entry.contractId:l.customer===entry.contractId&&!l.vehicle)&&l.expiryDate===entry.amcExpiry&&(l.planId&&entry.amcPlanId?l.planId===entry.amcPlanId:l.amcType===entry.amcType)).sort((a,b)=>b.at.localeCompare(a.at))[0]}
function logAmcContractReminder(key,id,note){let entry=amcContractEntries().find(e=>e.contractKey===key&&e.contractId===id);if(!entry)throw Error('AMC contract not found.');let before=structuredClone(db);db.amcReminderLogs=db.amcReminderLogs||[];db.amcReminderLogs.push({id:'AMC-R-'+Date.now(),customer:key==='bikes'?entry.customer:id,vehicle:key==='bikes'?id:'',planId:entry.amcPlanId,amcType:entry.amcType,expiryDate:entry.amcExpiry,at:new Date().toISOString(),note:String(note||'').slice(0,500),status:'User confirmed sent'});audit('AMC Reminder',entry.amcType+' reminder recorded by user');if(save('Reminder recorded')===false){db=before;return false}return true}
