function updateSharedAmcPlan(id,input){let plan=findAmcPlan(id);if(!plan)throw Error('Plan not found.');let name=String(input.name||'').trim(),months=Number(input.months),coverage=String(input.coverage||'').trim();if(!name||name.length>80)throw Error('Enter a plan name, up to 80 characters.');if(!Number.isInteger(months)||months<1||months>120)throw Error('Validity must be 1–120 whole months.');if(db.amcPlans.some(p=>p.id!==id&&p.name.toLowerCase()===name.toLowerCase()))throw Error('This plan name already exists.');let before=structuredClone(db),old=plan.name;for(let record of [...db.customers,...db.bikes])if(!record.amcPlanId&&record.amcType===old)record.amcPlanId=id;Object.assign(plan,{name,months,coverage:coverage.slice(0,1000)});db.lists['AMC Types']=(db.lists['AMC Types']||[]).map(v=>v===old?name:v);if(!db.lists['AMC Types'].includes(name))db.lists['AMC Types'].push(name);audit('AMC Plan',name+' updated; contract dates retained');if(save('AMC plan updated across linked modules')===false){db=before;return false}return true}
