function amcPlanUsage(plan){
  const linkedCustomers=db.customers.filter(customer=>customer.amcPlanId===plan.id||(!customer.amcPlanId&&customer.amcType===plan.name)).length;
  const linkedVehicles=db.bikes.filter(bike=>bike.amcPlanId===plan.id||(!bike.amcPlanId&&bike.amcType===plan.name)).length;
  return {linkedCustomers,linkedVehicles};
}
